//! Generated bytes cross stdin only. No generated command ever runs on the host.
use super::*;
use std::io::Read;
use std::process::{Command, Stdio};
use std::thread;

const LAUNCHER: &str = include_str!("runner.py");

pub(crate) struct DockerSandbox {
    pub image_id: String,
}

struct Captured {
    code: Option<i32>,
    stdout: String,
    stderr: String,
    truncated: bool,
    timed_out: bool,
}

fn drain(mut stream: impl Read, cap: usize) -> io::Result<(String, bool)> {
    let mut kept = Vec::new();
    let mut truncated = false;
    let mut buffer = [0u8; 4096];
    loop {
        let count = stream.read(&mut buffer)?;
        if count == 0 {
            break;
        }
        let remaining = cap.saturating_sub(kept.len());
        kept.extend_from_slice(&buffer[..count.min(remaining)]);
        truncated |= count > remaining;
    }
    Ok((String::from_utf8_lossy(&kept).into_owned(), truncated))
}

/// Drain both pipes even after the retention limit, avoiding pipe deadlock and unbounded RAM.
fn capture(
    command: &mut Command,
    input: Option<Vec<u8>>,
    budget: Duration,
) -> io::Result<Captured> {
    let mut child = command
        .stdin(if input.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    let stdout = child.stdout.take().expect("piped stdout");
    let stderr = child.stderr.take().expect("piped stderr");
    let writer = input.map(|bytes| {
        let mut stdin = child.stdin.take().expect("piped stdin");
        thread::spawn(move || stdin.write_all(&bytes))
    });
    let output_reader = thread::spawn(move || drain(stdout, MAX_OUTPUT_BYTES));
    let error_reader = thread::spawn(move || drain(stderr, MAX_OUTPUT_BYTES));
    let started = Instant::now();
    let (status, timed_out) = loop {
        match child.try_wait() {
            Ok(Some(status)) => break (status, false),
            Ok(None) if started.elapsed() < budget => thread::sleep(Duration::from_millis(20)),
            Ok(None) => {
                let _ = child.kill();
                break (child.wait()?, true);
            }
            Err(error) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(error);
            }
        }
    };
    if let Some(writer) = writer {
        // Early exit/timeout can close stdin; execution evidence records that outcome.
        let _ = writer
            .join()
            .map_err(|_| io::Error::other("sandbox input worker panicked"))?;
    }
    let (stdout, out_cut) = output_reader
        .join()
        .map_err(|_| io::Error::other("sandbox output worker panicked"))??;
    let (stderr, err_cut) = error_reader
        .join()
        .map_err(|_| io::Error::other("sandbox error worker panicked"))??;
    Ok(Captured {
        code: status.code(),
        stdout,
        stderr,
        truncated: out_cut || err_cut,
        timed_out,
    })
}

fn docker() -> Command {
    Command::new("docker")
}

impl DockerSandbox {
    pub fn preflight(budget: Duration) -> io::Result<Self> {
        let image =
            std::env::var("COMMUNITY_CODE_IMAGE").unwrap_or_else(|_| "lyra-code-python:1".into());
        if image.is_empty() || image.starts_with('-') || image.chars().any(char::is_whitespace) {
            return Err(invalid(
                "COMMUNITY_CODE_IMAGE must name a trusted local image",
            ));
        }
        let result = capture(
            docker().args([
                "image",
                "inspect",
                "--format",
                "{\"Id\":{{json .Id}},\"Os\":{{json .Os}},\"Volumes\":{{json (index .Config \"Volumes\")}}}",
                &image,
            ]),
            None,
            budget.min(Duration::from_secs(10)),
        )?;
        if result.timed_out || result.code != Some(0) || result.truncated {
            return Err(io::Error::other(
                "coding image unavailable; build it with: docker build -t lyra-code-python:1 docker/code-python",
            ));
        }
        let metadata: serde_json::Value =
            serde_json::from_str(&result.stdout).map_err(crate::errors::invalid_json)?;
        let item = &metadata;
        let id = item["Id"]
            .as_str()
            .filter(|id| id.starts_with("sha256:") && id.len() == 71)
            .ok_or_else(|| invalid("Docker did not resolve an immutable coding image ID"))?;
        if item["Os"].as_str() != Some("linux")
            || item["Volumes"]
                .as_object()
                .is_some_and(|volumes| !volumes.is_empty())
        {
            return Err(invalid("coding image must be Linux and declare no volumes"));
        }
        Ok(Self {
            image_id: id.into(),
        })
    }

    pub fn run(
        &mut self,
        files: &[CodeFile],
        tests: &str,
        budget: Duration,
    ) -> io::Result<Execution> {
        validate_files(files)?;
        validate_test_code(tests)?;
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(io::Error::other)?
            .as_nanos();
        let name = format!("lyra-code-{}-{nonce}", std::process::id());
        // Cleanup also covers spawn/write/inspect errors and unwinding. Never target another container.
        let guard = ContainerGuard { name: name.clone() };
        let started = Instant::now();
        let deadline = started + budget;
        let remaining = || {
            deadline
                .checked_duration_since(Instant::now())
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::TimedOut, "sandbox time budget exhausted")
                })
        };
        let created = capture(
            &mut create_command(&self.image_id, &name),
            None,
            remaining()?,
        )?;
        if created.code != Some(0) || created.timed_out || created.truncated {
            return Err(io::Error::other(format!(
                "Docker could not create sandbox: {}",
                created.stderr
            )));
        }
        let input = serde_json::to_vec(&serde_json::json!({"files":files,"tests":tests}))?;
        let result = capture(
            docker().args(["start", "--attach", "--interactive", &name]),
            Some(input),
            remaining()?,
        )?;
        // Killing the CLI does not kill a container: explicitly remove it on timeout.
        if result.timed_out {
            drop(guard);
            return Ok(Execution {
                exit_code: None,
                timed_out: true,
                oom_killed: false,
                output_truncated: result.truncated,
                stdout: result.stdout,
                stderr: result.stderr,
                elapsed_ms: started.elapsed().as_millis(),
                infrastructure_error: None,
            });
        }
        let inspected = capture(
            docker().args(["inspect", "--format", "{{json .State}}", &name]),
            None,
            remaining()?.min(Duration::from_secs(5)),
        )?;
        let state = if inspected.code == Some(0) && !inspected.timed_out && !inspected.truncated {
            serde_json::from_str::<serde_json::Value>(&inspected.stdout).ok()
        } else {
            None
        };
        let exit_code = state
            .as_ref()
            .and_then(|state| state["ExitCode"].as_i64())
            .and_then(|code| i32::try_from(code).ok());
        let oom_killed = state
            .as_ref()
            .and_then(|state| state["OOMKilled"].as_bool())
            .unwrap_or(false);
        let valid_exit = state
            .as_ref()
            .is_some_and(|state| state["Status"] == "exited" && state["Error"] == "");
        let infrastructure_error = if !valid_exit {
            Some("Docker did not retain a clean container exit state".into())
        } else if result.code != exit_code {
            Some("Docker attach and container exit codes disagree".into())
        } else {
            None
        };
        drop(guard);
        Ok(Execution {
            exit_code,
            timed_out: false,
            oom_killed,
            output_truncated: result.truncated,
            stdout: result.stdout,
            stderr: result.stderr,
            elapsed_ms: started.elapsed().as_millis(),
            infrastructure_error,
        })
    }
}

fn create_command(image_id: &str, name: &str) -> Command {
    let mut command = docker();
    command.args([
        "create",
        "--pull",
        "never",
        "--interactive",
        "--name",
        name,
        "--network",
        "none",
        "--read-only",
        "--user",
        "10001:10001",
        "--cap-drop",
        "ALL",
        "--security-opt",
        "no-new-privileges:true",
        "--cpus",
        "1",
        "--memory",
        "256m",
        "--memory-swap",
        "256m",
        "--pids-limit",
        "64",
        "--ulimit",
        "nofile=128:128",
        "--ulimit",
        "fsize=1048576:1048576",
        "--tmpfs",
        "/workspace:rw,noexec,nosuid,nodev,size=64m,uid=10001,gid=10001,mode=0700",
        "--tmpfs",
        "/tmp:rw,noexec,nosuid,nodev,size=16m,uid=10001,gid=10001,mode=0700",
        "--shm-size",
        "8m",
        "--ipc",
        "private",
        "--workdir",
        "/workspace",
        "--env",
        "HOME=/tmp",
        "--env",
        "PYTHONDONTWRITEBYTECODE=1",
        "--env",
        "PYTHONUNBUFFERED=1",
        "--log-driver",
        "none",
        "--restart",
        "no",
        "--entrypoint",
        "python",
        image_id,
        "-I",
        "-B",
        "-c",
        LAUNCHER,
    ]);
    command
}

struct ContainerGuard {
    name: String,
}
impl Drop for ContainerGuard {
    fn drop(&mut self) {
        match capture(
            docker().args(["rm", "--force", "--volumes", &self.name]),
            None,
            Duration::from_secs(5),
        ) {
            Ok(result) if result.code == Some(0) => {}
            result => crate::diagnostics::event(
                "coding.cleanup_failed",
                serde_json::json!({"container":self.name,"reason": match result { Ok(result) => result.stderr, Err(error) => error.to_string() }}),
            ),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn docker_contract_has_no_host_mount_or_network_and_uses_immutable_image() {
        let command = create_command("sha256:trusted", "test-container");
        let args: Vec<_> = command
            .get_args()
            .map(|arg| arg.to_str().unwrap())
            .collect();
        for pair in [
            ["--network", "none"],
            ["--cap-drop", "ALL"],
            ["--user", "10001:10001"],
            ["--security-opt", "no-new-privileges:true"],
            ["--pids-limit", "64"],
            ["--memory", "256m"],
        ] {
            assert!(args.windows(2).any(|args| args == pair));
        }
        assert!(args.contains(&"--read-only"));
        for forbidden in [
            "--privileged",
            "--mount",
            "--volume",
            "-v",
            "--env-file",
            "--use-api-socket",
        ] {
            assert!(!args.contains(&forbidden));
        }
        assert!(
            args.windows(2)
                .any(|args| args == ["--entrypoint", "python"])
        );
    }

    #[test]
    fn capture_drains_large_output_and_enforces_a_deadline() {
        let mut noisy = Command::new("python3");
        noisy.args([
            "-c",
            "import sys; print('a'*100000); sys.stderr.write('b'*100000)",
        ]);
        let result = capture(&mut noisy, None, Duration::from_secs(5)).unwrap();
        assert_eq!(result.code, Some(0));
        assert_eq!(result.stdout.len(), MAX_OUTPUT_BYTES);
        assert_eq!(result.stderr.len(), MAX_OUTPUT_BYTES);
        assert!(result.truncated);
        let mut slow = Command::new("python3");
        slow.args(["-c", "import time; time.sleep(30)"]);
        assert!(
            capture(&mut slow, None, Duration::from_millis(100))
                .unwrap()
                .timed_out
        );
    }

    #[test]
    #[ignore = "requires the locally built Docker coding image"]
    fn live_docker_isolates_code_and_kills_overruns() {
        let mut sandbox = DockerSandbox::preflight(Duration::from_secs(10)).unwrap();
        let files = vec![CodeFile {
            path: "solution.py".into(),
            content: "def add(a,b): return a+b".into(),
        }];
        let tests = "import unittest, os, socket\nfrom solution import add\nclass Checks(unittest.TestCase):\n def test_sum(self): self.assertEqual(add(2,3),5)\n def test_identity(self): self.assertNotEqual(os.getuid(),0)\n def test_host(self): self.assertFalse(os.path.exists('/var/run/docker.sock'))\n def test_root(self):\n  with self.assertRaises(OSError): open('/root-write-test','w')\n def test_network(self):\n  with self.assertRaises(OSError): socket.create_connection(('1.1.1.1',443),timeout=1)\n";
        let result = sandbox.run(&files, tests, Duration::from_secs(10)).unwrap();
        assert!(result.passed(), "{result:?}");
        let generated = test_source(&[
            CodeTest { name: "module_interface".into(), body: "self.assertEqual(solution.add(2, 3), 5)".into() },
            CodeTest { name: "public_interface".into(), body: "self.assertEqual(add(-2, 3), 1)\nwith self.assertRaises(TypeError):\n    add(None, 2)".into() },
        ]).unwrap();
        assert!(
            sandbox
                .run(&files, &generated, Duration::from_secs(10))
                .unwrap()
                .passed()
        );
        let empty = sandbox
            .run(&files, "# no tests", Duration::from_secs(10))
            .unwrap();
        assert!(!empty.passed(), "zero tests must not pass");
        let early_exit = sandbox
            .run(&files, "import sys; sys.exit(0)", Duration::from_secs(10))
            .unwrap();
        assert!(
            !early_exit.passed(),
            "import-time exit must not count as success"
        );
        let slow = sandbox
            .run(
                &files,
                "import time; time.sleep(60)",
                Duration::from_secs(2),
            )
            .unwrap();
        assert!(slow.timed_out);
        let noisy = sandbox
            .run(&files, "print('x'*100000)", Duration::from_secs(10))
            .unwrap();
        assert!(noisy.output_truncated);
        assert!(!noisy.passed());
        let exhausted = sandbox
            .run(
                &files,
                "data = bytearray(1024 * 1024 * 1024)",
                Duration::from_secs(10),
            )
            .unwrap();
        assert!(exhausted.oom_killed, "{exhausted:?}");
        assert!(!exhausted.passed());
    }
}
